#if (defined GPU_DEMO_TASK_FILL)

/* 任务ID定义 */
#define GPU_FILL_TASK_ID	1

/* 控件DI定义 */
#define GPU_FILL_ELEMENT	1

/* 透明度定义，0~100 */
#define GPU_FILL_ALPHA		50

/* 颜色值定义，RGB888 */
#define GPU_FILL_COLOR		0x00ff00

/* 任务显示坐标定义 */
#define GPU_FILL_X			50
#define GPU_FILL_Y			50

/* 任务显示大小定义 */
#define GPU_FILL_W			80
#define GPU_FILL_H			80

/* 任务旋转角度定义 */
#define GPU_FILL_ANGLE		45

/* 任务缩放倍率定义 */
#define GPU_FILL_RATIO		0.5f

#endif



#if defined GPU_DEMO_TASK_FILL && GPU_DEMO_TASK_FILL

/* 创建GPU填充任务示例 */
void gpu_demo_create_fill_task(pJLGPUTaskHead_t head)
{
    /* 填充颜色ARGB8888 */
    u8 a = GPU_FILL_ALPHA;
    u8 r = (GPU_FILL_COLOR >> 16) & 0xff;
    u8 g = (GPU_FILL_COLOR >> 8) & 0xff;
    u8 b = (GPU_FILL_COLOR) & 0xff;

    /* 创建task_param参数结构体，并设置任务ID，控件ID，填充颜色 */
    jlgpu_task_fill_param_init(GPU_FILL_TASK_ID, GPU_FILL_ELEMENT, a, r, g, b);

    /* 配置填充位置区域 */
    task_param.draw.left   = GPU_FILL_X;
    task_param.draw.top    = GPU_FILL_Y;
    task_param.draw.width  = GPU_FILL_W;
    task_param.draw.height = GPU_FILL_H;

    /* 配置填充的父控件区域为整个屏幕 */
    jlgpu_get_win_rect(&task_param.area);

    /* 创建GPU任务，并添加到head任务链中 */
    jlgpu_update_task_by_id(head, GPU_FILL_TASK_ID, GPU_FILL_ELEMENT, &task_param);
}

#endif



#if defined GPU_DEMO_TASK_FILL_AFFINE && GPU_DEMO_TASK_FILL_AFFINE

/* 创建填充仿射变换任务 */
void gpu_demo_create_fill_affine(pJLGPUTaskHead_t head)
{
    /* 填充颜色ARGB8888 */
    u8 a = GPU_FILL_ALPHA;
    u8 r = (GPU_FILL_COLOR >> 16) & 0xff;
    u8 g = (GPU_FILL_COLOR >> 8) & 0xff;
    u8 b = (GPU_FILL_COLOR) & 0xff;

    /* 创建task_param参数结构体，并设置任务ID，控件ID，填充颜色 */
    jlgpu_task_fill_param_init(GPU_FILL_TASK_ID, GPU_FILL_ELEMENT, a, r, g, b);

    /* 配置填充位置区域 */
    task_param.draw.left   = GPU_FILL_X;
    task_param.draw.top    = GPU_FILL_Y;
    task_param.draw.width  = GPU_FILL_W;
    task_param.draw.height = GPU_FILL_H;

    /* 配置填充的父控件区域为整个屏幕 */
    jlgpu_get_win_rect(&task_param.area);

    /* 缩放使能 */
    task_param.scale_en = true;
    task_param.fill.tran.ratio_w = GPU_FILL_RATIO;
    task_param.fill.tran.ratio_h = GPU_FILL_RATIO;

    /* 旋转使能 */
    task_param.rotate_en = true;
    task_param.fill.tran.rotate_cx = 40;// GPU_FILL_W / 2;
    task_param.fill.tran.rotate_cy = 40;// GPU_FILL_H / 2;
    task_param.fill.tran.rotate_dx = 160;
    task_param.fill.tran.rotate_dy = 193;
    task_param.fill.tran.rotate_angle = GPU_FILL_ANGLE;

    /* 创建GPU任务，并添加到head任务链中 */
    jlgpu_update_task_by_id(head, GPU_FILL_TASK_ID, GPU_FILL_ELEMENT, &task_param);
}

#endif



