void gpu_demo_create_fill_mask(pJLGPUTaskHead_t head)
{
    /* 填充颜色ARGB8888 */
    u8 a = GPU_FILL_ALPHA;
    u8 r = (GPU_FILL_COLOR >> 16) & 0xff;
    u8 g = (GPU_FILL_COLOR >> 8) & 0xff;
    u8 b = (GPU_FILL_COLOR) & 0xff;

    jlgpu_task_fill_param_init(GPU_FILL_TASK_ID, GPU_FILL_ELEMENT, a, r, g, b);
    task_param.task_type = GPU_TASK_CUSTOM | GPU_FILL_MASK;

    task_param.draw.left   = GPU_FILL_X;
    task_param.draw.top    = GPU_FILL_Y;
    task_param.draw.width  = GPU_FILL_W;
    task_param.draw.height = GPU_FILL_H;

    jlgpu_get_win_rect(&task_param.area);

    /* 配置MASK参数 */
    task_param.fill.mask.rect.left   = task_param.draw.left;	// mask绘制区域，与draw区域一样即可
    task_param.fill.mask.rect.top    = task_param.draw.top;
    task_param.fill.mask.rect.width  = task_param.draw.width;
    task_param.fill.mask.rect.height = task_param.draw.height;

    /* MASK图片数据和格式 */
    task_param.fill.mask.mask_data = (u8 *)icon_80x80_map;
    task_param.fill.mask.mask_format = GPU_MASK_FORMAT_A8;

    /* 注意，凡用到图片的功能，都需配置task_param.image，至少配置图片宽、高 */
    task_param.image.width  = GPU_FILL_W;
    task_param.image.height = GPU_FILL_H;

    /* 创建GPU任务 */
    jlgpu_update_task_by_id(head, GPU_FILL_TASK_ID, GPU_FILL_ELEMENT, &task_param);
}

